# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validatorsBySchema: WeakMap<object, ValidateFunction>;
}

interface ValidationErrorDetails {
  keyword?: string;
  instancePath?: string;
  dataPath?: string;
  params?: {missingProperty?: string; type?: string};
}

function describeValidationError(error: ValidationErrorDetails | undefined): {property: string; reason: string} {
  const property = validationPropertyPath(error?.instancePath, error?.dataPath);
  if (error?.keyword === 'required') {
    return {property: error.params?.missingProperty ?? 'input', reason: 'is required'};
  }
  if (error?.keyword === 'type') {
    return {
      property,
      reason: `must be of type ${error.params?.type ?? 'the declared schema type'}`,
    };
  }
  return {
    property,
    reason: `failed ${error?.keyword ?? 'schema validation'}`,
  };
}

function validationPropertyPath(instancePath: string | undefined, dataPath: string | undefined): string {
  if (instancePath) {
    return instancePath
      .split('/')
      .slice(1)
      .map(segment => segment.replace(/~1/g, '/').replace(/~0/g, '~'))
      .join('.');
  }
  const path = dataPath?.replace(/^\.?/, '').replace(/\[['"]?([^'"\]]+)['"]?\]/g, '.$1');
  return (
    path
      ?.replace(/^input(?:[./]|$)/, '')
      .replace(/^\/+/, '')
      .replace(/\//g, '.') || 'input'
  );
}

function schemaCompilationError(toolName: string, error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(`Failed to compile inputSchema for tool '${toolName}': ${message}`);
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw schemaCompilationError(resolved.name, error);
      }
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validatorsBySchema: new WeakMap(),
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns schema rejections; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator =
      tool.validator ?? tool.validatorsBySchema.get(definition.inputSchema) ?? this.ajv.compile(definition.inputSchema);
    if (!tool.validator) {
      tool.validatorsBySchema.set(definition.inputSchema, validator);
    }
    if (!validator(input)) {
      const error = validator.errors?.[0] as ValidationErrorDetails | undefined;
      const {property, reason} = describeValidationError(error);
      log.warn('tool', 'input rejected', {name, property, keyword: error?.keyword});
      return {result: `Input validation failed: property '${property}' ${reason}.`};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

function exposeLegacyDataPath(registry: ToolRegistry, path: (instancePath: string) => string): void {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
  };
  const originalCompile = ajv.compile.bind(ajv);
  ajv.compile = schema => {
    const validator = originalCompile(schema);
    const legacyValidator = ((input: Record<string, unknown>) => {
      const valid = validator(input);
      if (!valid && validator.errors) {
        const error = validator.errors[0] as {dataPath?: string; instancePath?: string};
        error.dataPath = path(error.instancePath ?? '');
        delete error.instancePath;
      }
      legacyValidator.errors = validator.errors;
      return valid;
    }) as ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
    return legacyValidator;
  };
}

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executorCalls = {value: 0};
    registerWeatherTool(registry, executorCalls);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls: executorCalls.value,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports the expected type for a rejected property without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      resultNamesFieldAndType: response.result.includes('identifier') && response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
      executorCalls,
    }).toEqual({resultNamesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a nested rejected property using its field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_profile',
        description: 'Look up a profile',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {name: {type: 'string'}},
            },
          },
          required: ['profile'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_profile', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a rejected property when the validator exposes a legacy data path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => instancePath.replace(/^\//, '.'));
    registry.register(
      () => ({
        name: 'legacy_path',
        description: 'Validate a legacy path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('strips a legacy input root from a rejected property path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_root_path',
        description: 'Validate a legacy root path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_root_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('normalizes a slash-separated legacy input root in a rejected path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_slash_path',
        description: 'Validate a slash-separated legacy path',
        inputSchema: {type: 'object', properties: {profile: {type: 'object', properties: {name: {type: 'string'}}}}},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_slash_path', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('names the tool when a static schema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_static_schema',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_static_schema/);
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('caches a function-valued schema validator by object reference', async () => {
    const registry = new ToolRegistry();
    const ajv = Reflect.get(registry, 'ajv') as {
      compile: (schema: object) => unknown;
    };
    const originalCompile = ajv.compile.bind(ajv);
    let compileCalls = 0;
    ajv.compile = schema => {
      compileCalls += 1;
      return originalCompile(schema);
    };
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'cached_weather',
        description: 'Get weather for a location',
        inputSchema: schema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('cached_weather', {location: 'Paris'});
    schema.required = ['city'];
    const response = await registry.execute('cached_weather', {location: 'Paris'});

    expect({compileCalls, result: response.result, executorCalls}).toEqual({
      compileCalls: 1,
      result: 'sunny',
      executorCalls: 2,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('compiles a static schema once at registration and reuses it across executions', async () => {
    const registry = new ToolRegistry();
    const ajv = Reflect.get(registry, 'ajv') as {
      compile: (schema: object) => unknown;
    };
    const originalCompile = ajv.compile.bind(ajv);
    let compileCalls = 0;
    ajv.compile = schema => {
      compileCalls += 1;
      return originalCompile(schema);
    };
    registry.register(
      {
        name: 'static_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => JSON.stringify(input)
    );

    const results = await Promise.all(
      Array.from({length: 10}, () => registry.execute('static_weather', {location: 'Paris'}))
    );

    expect({compileCalls, resultCount: results.length}).toEqual({compileCalls: 1, resultCount: 10});
  });
});

# Validate tool input against the registered inputSchema

Issue: re-cinq/HALEngine#37
Labels: priority:medium, type:feature, size:M, area:tools, epic:extension-points

Part of #35

## Why

`ToolRegistry.execute` looks a tool up, logs the input's key names, and calls the executor
without ever checking the declared `inputSchema` (`src/orchestration/tools/registry.ts`).
Every tool declares a JSON Schema (`src/types/ai.ts`) that is handed verbatim to both
providers, but nothing validates what comes back from the model. The shipped example shows the
shape of the problem: `example/weather-tool.ts` declares `location` as a required string, then
casts and defaults it (`(input.location as string) || 'Unknown'`) with a comment warning the reader
that `inputSchema` shapes what the model sends but does not enforce it. That is the careful version,
written by the people who wrote the engine — and it still answers a malformed call with a
confidently formatted forecast for `'Unknown'` rather than telling the model it got the call wrong.

The registry currently pushes this check onto each tool's own executor, leaving every consumer
to implement it itself — differently each time, or not at all. A tool that receives unexpected input must fail
in one predictable, known way before the rest of this epic's tool work can be built on top
of it.

## What to do

Validate `input` against the resolved tool definition's `inputSchema` inside
`ToolRegistry.execute`, before the executor runs, using a JSON Schema validator (`ajv`
unless the build proves otherwise) added to `dependencies` — not a second, hand-written
schema in a different format, since the schema already has to match what is handed to the
providers.

Compile a static tool's schema once at `register` time so a broken schema fails at startup,
not mid-conversation; a schema produced by a function-valued `ToolDefinitionSource`
resolves and compiles per call, cached by the resolved schema object.

A rejection returns a `ToolResponse` (`{result: '<what was wrong>'}`) rather than throwing,
so a malformed call becomes something the model can read and correct within the existing
`DEFAULT_MAX_TOOL_ROUNDS = 5` budget, instead of ending the whole conversation with a
generic transport error. Validation enforces `required`, declared types and `enum` only —
it does not inject `additionalProperties: false`, coerce types, or apply defaults, and
there is no opt-out flag.

Update `docs/adding-a-tool.md`, `README.md` and `.specify/spec.md` to match.

## Acceptance criteria

- [ ] `ToolRegistry.execute` validates `input` against the resolved definition's
      `inputSchema` before calling the executor; on failure it returns a `ToolResponse`
      whose `result` describes the failure, and the executor is never invoked
- [ ] A new `src/orchestration/tools/registry.test.ts` (the registry has no test file today)
      registers a tool requiring a `location` string, calls `execute` with `{}`, and
      asserts the returned result names `location` as required and the executor's call
      count is `0`
- [ ] A test asserts valid input with an unlisted extra property is passed through to the
      executor unchanged (`toEqual`, so an added default or coerced value fails the test) —
      exactly once
- [ ] A test asserts a wrong-typed field (a number where a string is required) is rejected
      with a message naming the field path and the expected type, and that the message does
      **not** contain the offending value
- [ ] A test asserts `register` throws at registration time for an uncompilable schema, and
      that the thrown message names the tool
- [ ] A test asserts a function-valued tool definition whose returned schema differs between
      calls is validated against the schema current at that call, not a stale cached one
- [ ] A test asserts a static tool's schema is compiled once across ten `execute` calls
- [ ] A tool-loop test in `chatOrchestrator.test.ts` drives a stub provider through a
      rejected tool call followed by a corrected retry, and asserts `processMessage`
      resolves — not rejects — with the rejection text visible to the provider on the next
      round
- [ ] `execute` still throws `Unknown tool: <name>` for an unregistered name, unchanged,
      pinned by a test
- [ ] Rejection messages and log lines name the failing property paths and the constraint
      that failed, and never a property **value**. Tool input is where identifying data
      enters the engine and the engine redacts nothing today. A test asserts a rejected
      payload containing an identifying field produces no log line and no returned text
      containing that field's value
- [ ] `execute` carries a **one-line** doc comment — `re-lint/max-comment-lines` rejects a
      `@param`/`@returns`/`@throws` block — and the full contract (rejection `ToolResponse` for input
      the schema rejects, throw only for an unknown tool name) is stated in
      `specs/hal-engine-tool-input-validation/spec.md`, which the comment points at
- [ ] The validator is in `package.json` `dependencies`, not `peerDependencies` or
      `devDependencies`, and
      `npm run build && node --input-type=module -e "import('./dist/index.js')"` exits `0`
- [ ] `README.md` states what the registry now does, and the claim is true rather than
      merely present
- [ ] `docs/adding-a-tool.md` no longer tells executors to cast defensively and handle
      missing input; it states that input reaching an executor has already passed the
      declared schema, that unknown keys may still be present, and that a rejection is
      returned to the model rather than thrown
- [ ] `.specify/spec.md` records that a rejection is a tool result (not an exception), that
      the tool-round bound is what stops a retry cycle from spinning, and that extra
      properties pass through unmodified
- [ ] The PR body states the migration note: an executor that used to hand-validate its
      input now receives only input the schema already accepts, and a tool that relied on
      seeing malformed input to produce its own error message stops seeing it. The version
      bump is MINOR
- [ ] Every test this issue adds cites the statement it validates with an inline
      `([validated by ...])` link in a `specs/**` or `adrs/**` file, and the statements exist
      before the tests do. `re-lint/require-spec-link` fails the build on an uncited test, so the
      spec edits are part of this issue rather than a follow-up
- [ ] `CHANGELOG.md` carries an entry for this change, written for somebody reading it on npm
      rather than somebody reading this repo's log. CI runs `scripts/check-changelog.sh` and
      fails any PR touching a non-test file under `src/` without one
- [ ] `npm run build`, `npm run typecheck`, `npm test`, `npm run eslint` (`--max-warnings 0`)
      and `npm run prettier:check` pass, with no `any` in the changed public surface

## Tech notes

Today's `throw` in `registry.ts` propagates through the orchestrator's tool-call
`Promise.all`, out of the processing loop's `try`, fires `onError`, and reaches the
WebSocket error handler, which sends a generic "Failed to process message" and never sends
the stream-end frame. That end-to-end path is why a rejection has to be a returned
`ToolResponse` instead of a throw.

Deliberately out of scope: the `Unknown tool: <name>` throw stays as-is — the same failure
class handled the opposite way, which is an intentional split, but changing it affects
direct callers and is tracked as *Return an unknown tool name to the model instead of
throwing*. Also out of scope: validating tool *output*; hallucination detection and an
evaluation harness; per-tool authorization — a schema-valid call for someone else's data is still
valid, and authorization is a separate `ToolContext` boundary concern that no issue in this epic
owns (*Let a consumer decline a tool call through a `beforeToolCall` hook* is a veto seam, not an
authorization model); retry, timeout
and rate limiting around tool execution; and any actual tool implementation, which is
written against this contract later.


