import {ToolRegistry} from './registry.js';

function exposeLegacyDataPath(registry: ToolRegistry, path: (instancePath: string) => string): void {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
  };
  const originalCompile = ajv.compile.bind(ajv);
  ajv.compile = schema => {
    const validator = originalCompile(schema);
    const legacyValidator = ((input: Record<string, unknown>) => {
      const valid = validator(input);
      if (!valid && validator.errors) {
        const error = validator.errors[0] as {dataPath?: string; instancePath?: string};
        error.dataPath = path(error.instancePath ?? '');
        delete error.instancePath;
      }
      legacyValidator.errors = validator.errors;
      return valid;
    }) as ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
    return legacyValidator;
  };
}

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

function countValidatorCompilations(registry: ToolRegistry): {get: () => number} {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => unknown;
  };
  const originalCompile = ajv.compile.bind(ajv);
  let compileCalls = 0;
  ajv.compile = schema => {
    compileCalls += 1;
    return originalCompile(schema);
  };
  return {get: () => compileCalls};
}

